using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;
namespace LightingBlocks.Editor {public static class CreatureAudit {
public static void Run(){var log=new StringBuilder();foreach(var name in new[]{"Rabbit","Bird"}){var path="Assets/LightingBlocks/Art/SpectralForest/Twilight/Models/"+name+".fbx";var model=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(path));log.AppendLine(name);foreach(var t in model.GetComponentsInChildren<Transform>())log.AppendLine(AnimationUtility.CalculateTransformPath(t,model.transform)+" p="+t.localPosition+" r="+t.localEulerAngles);foreach(var clip in AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__"))){var bindings=AnimationUtility.GetCurveBindings(clip);var varying=bindings.Count(b=>{var c=AnimationUtility.GetEditorCurve(clip,b);return c!=null&&c.keys.Length>1&&c.keys.Max(k=>k.value)-c.keys.Min(k=>k.value)>.001f;});clip.SampleAnimation(model,0);var r=model.GetComponentInChildren<SkinnedMeshRenderer>();var mesh=new Mesh();r.BakeMesh(mesh);var before=mesh.vertices;clip.SampleAnimation(model,clip.length*.31f);r.BakeMesh(mesh);var after=mesh.vertices;float movement=0;for(int i=0;i<before.Length;i++)movement=Mathf.Max(movement,Vector3.Distance(before[i],after[i]));log.AppendLine(clip.name+" duration="+clip.length+" curves="+bindings.Length+" varying="+varying+" skinMotion="+movement);UnityEngine.Object.DestroyImmediate(mesh);}UnityEngine.Object.DestroyImmediate(model);}File.WriteAllText("Library/CreatureAudit.txt",log.ToString());}
}}
